<template><q-page class="pagina-inmuebles"><header><div><span>INMOBILIARIA</span><h1>Inmuebles</h1><p>Venta, alquiler y anticrético administrados por Comarapa Market.</p></div><q-btn v-if="auth.estaAutenticado" color="primary" icon="add_home" label="Publicar inmueble" unelevated @click="formulario=!formulario"/></header><q-slide-transition><q-card v-show="formulario" flat bordered class="form-inmueble"><q-card-section><q-form class="grid-form" @submit="publicar"><q-input v-model="titulo" outlined label="Título" :rules="[requerido]"/><q-input v-model="ciudad" outlined label="Ciudad" :rules="[requerido]"/><q-input v-model="zona" outlined label="Zona (opcional)"/><q-select v-model="tipo" outlined emit-value map-options :options="tipos" label="Tipo de inmueble"/><q-select v-model="operacion" outlined emit-value map-options :options="operaciones" label="Operación"/><q-input v-model.number="precio" outlined type="number" prefix="Bs" label="Precio solicitado"/><q-input v-model="descripcion" class="ancho" outlined type="textarea" autogrow label="Descripción" :rules="[requerido]"/><q-file v-model="imagenes" class="ancho" outlined multiple accept="image/*" label="Imágenes (1 a 8)" :rules="[(v)=>v?.length>0||'Agrega al menos una imagen']"><template #prepend><q-icon name="photo_library"/></template></q-file><q-btn class="ancho" type="submit" color="primary" label="Enviar a revisión" icon="send" :loading="enviando" unelevated/></q-form></q-card-section></q-card></q-slide-transition><h2>Inmuebles disponibles</h2><div v-if="inmuebles.length" class="grid-inmuebles"><q-card v-for="i in inmuebles" :key="i.id" flat bordered><q-img :src="i.imagenes[0]" ratio="1.4"/><q-card-section><q-badge color="primary">{{i.tipo_operacion}}</q-badge><h3>{{i.titulo}}</h3><strong>Bs {{i.precio}}</strong><p><q-icon name="place"/> {{i.ciudad}}{{i.zona?' · '+i.zona:''}}</p></q-card-section></q-card></div><div v-else class="vacio">Todavía no hay inmuebles aprobados.</div></q-page></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{useQuasar}from'quasar';import{useTiendaAutenticacion}from'src/stores/tiendaAutenticacion';import{crearInmueble,listarInmuebles,type Inmueble}from'src/services/servicioServiciosEspeciales';import{obtenerMensajeError}from'src/services/servicioApi';const auth=useTiendaAutenticacion(),q=useQuasar(),formulario=ref(false),titulo=ref(''),ciudad=ref('Comarapa'),zona=ref(''),tipo=ref('casa'),operacion=ref('venta'),precio=ref<number|null>(null),descripcion=ref(''),imagenes=ref<File[]>([]),enviando=ref(false),inmuebles=ref<Inmueble[]>([]),requerido=(v:string)=>!!v?.trim()||'Campo obligatorio';const tipos=[{label:'Casa',value:'casa'},{label:'Terreno',value:'terreno'},{label:'Departamento',value:'departamento'},{label:'Local',value:'local'},{label:'Quinta',value:'quinta'},{label:'Otro',value:'otro'}],operaciones=[{label:'Venta',value:'venta'},{label:'Alquiler',value:'alquiler'},{label:'Anticrético',value:'anticretico'}];async function cargar(){inmuebles.value=await listarInmuebles()}async function publicar(){if(!precio.value)return;const f=new FormData();f.append('titulo',titulo.value);f.append('ciudad',ciudad.value);f.append('zona',zona.value);f.append('tipo_inmueble',tipo.value);f.append('tipo_operacion',operacion.value);f.append('precio_solicitado',String(precio.value));f.append('descripcion',descripcion.value);imagenes.value.slice(0,8).forEach(x=>f.append('imagenes[]',x));enviando.value=true;try{await crearInmueble(f);formulario.value=false;titulo.value='';descripcion.value='';imagenes.value=[];q.notify({type:'positive',message:'Inmueble enviado a revisión.'})}catch(e){q.notify({type:'negative',message:obtenerMensajeError(e)})}finally{enviando.value=false}}onMounted(()=>void cargar())</script>
<style scoped lang="scss">.pagina-inmuebles{width:min(100%,1180px);margin:auto;padding:clamp(20px,4vw,42px) clamp(14px,3vw,28px) 110px}.pagina-inmuebles>header{display:flex;align-items:center;justify-content:space-between;gap:18px}.pagina-inmuebles header h1,.pagina-inmuebles header p{margin:0}.pagina-inmuebles header span{color:var(--verde-principal);font-weight:800;font-size:.72rem;letter-spacing:.08em}.pagina-inmuebles header p{color:var(--texto-secundario)}.form-inmueble{margin:22px 0;border-radius:20px}.grid-form{display:grid;grid-template-columns:1fr 1fr;gap:14px}.ancho{grid-column:1/-1}.pagina-inmuebles>h2{margin-top:30px}.grid-inmuebles{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:18px}.grid-inmuebles .q-card{overflow:hidden;border-radius:18px}.grid-inmuebles h3{margin:8px 0 2px}.grid-inmuebles strong{color:var(--verde-principal);font-size:1.25rem}.grid-inmuebles p{color:var(--texto-secundario)}.vacio{padding:50px;border:1px dashed var(--borde);border-radius:18px;text-align:center}@media(max-width:650px){.pagina-inmuebles>header{align-items:flex-start;flex-direction:column}.grid-form{grid-template-columns:1fr}.ancho{grid-column:auto}}</style>
